function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (cache.has(arg)) return cache.get(arg);
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}
const fastFib = memoize((n) => (n <= 1 ? n : fastFib(n - 1) + fastFib(n - 2)));
console.log(fastFib(40));

