async function generateCertificate(data) {
  const [{ jsPDF }, QRCode] = await Promise.all([
    import('jspdf'),
    import('qrcode'),
  ]);
  const doc = new jsPDF({ orientation: 'landscape' });
  const qr = await QRCode.toDataURL(data.verifyUrl);
  doc.addImage(qr, 'PNG', 220, 140, 35, 35);
  return doc;
}
